import {drawCachedSkin} from './skin-details.js';

export const ZOO_STAGES=Object.freeze([
 ['hamster','햄스터',16,'#dca66e',1],['cat','고양이',22,'#c29a78',3],['dog','강아지',28,'#bd8659',6],
 ['rabbit','토끼',35,'#ead8d1',10],['fox','여우',42,'#db8751',15],['raccoon','너구리',50,'#999a8b',21],
 ['koala','코알라',59,'#9daaaa',28],['panda','판다',69,'#c2c6b5',36],['lion','사자',80,'#d6a24d',45],
 ['tiger','호랑이',91,'#df9a43',55],['gorilla','고릴라',102,'#7a817e',80],['elephant','코끼리',113,'#97a7ae',120],
 ['giraffe','기린',123,'#ddb564',180],['dolphin','돌고래',133,'#7badc4',260],['whale','고래',143,'#4f89a5',400],
].map(([id,name,radius,color,points])=>Object.freeze({id,name,radius,color,points})));
const T=Math.PI*2;
function oval(c,x,y,rx,ry,color,line,w=.8,rot=0){c.beginPath();c.ellipse(x,y,rx,ry,rot,0,T);if(color){c.fillStyle=color;c.fill();}if(line){c.strokeStyle=line;c.lineWidth=w;c.stroke();}}
function gradient(c,colors){const g=c.createLinearGradient(-20,-35,25,40);colors.forEach((v,i)=>g.addColorStop(i/(colors.length-1),v));return g;}
function poly(c,p,color,line,w=1){c.beginPath();p.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fillStyle=color;c.fill();if(line){c.strokeStyle=line;c.lineWidth=w;c.stroke();}}
function line(c,p,color='#493d36',w=1.3){c.beginPath();p.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.strokeStyle=color;c.lineWidth=w;c.stroke();}
function head(c,colors,rx=34,ry=32,y=5){oval(c,1,7,rx+1,ry,'#26352b17');oval(c,0,y,rx,ry,gradient(c,colors),'#554b3e77',.65);}
function eyes(c,x=13,y=1,r=2.6){for(const side of [-1,1]){oval(c,side*x,y,r,r*1.18,'#302f2b');oval(c,side*x-.7,y-1,r*.3,r*.3,'#ffffffd9');}}
function nose(c,x=0,y=12,size=3,color='#534238'){oval(c,x,y,size,size*.7,color);line(c,[[x,y+1],[x,y+5]],color,.9);c.beginPath();c.moveTo(x-5,y+4);c.quadraticCurveTo(x-2,y+8,x,y+5);c.quadraticCurveTo(x+2,y+8,x+5,y+4);c.strokeStyle=color;c.lineWidth=.9;c.stroke();}
function ear(c,x,y,rx,ry,color,inside='#dca9a2',rot=0){oval(c,x,y,rx,ry,color,'#554b3e66',.65,rot);oval(c,x,y,rx*.58,ry*.58,inside,null,.8,rot);}
function cheeks(c,x=23,y=12){oval(c,-x,y,4,2.3,'#d9897d44');oval(c,x,y,4,2.3,'#d9897d44');}
function whiskers(c,x=20,y=12){for(const side of [-1,1])for(const d of [-1,1])line(c,[[side*x,y+d],[side*(x+12),y+d*4]],'#745d4977',.65);}
function paint(c,level){c.save();c.lineCap='round';c.lineJoin='round';
 if(level===0){ear(c,-22,-22,10,11,'#cb9c70');ear(c,22,-22,10,11,'#cb9c70');head(c,['#f4d7af','#d49e69','#ae7850'],33,31,5);oval(c,0,17,23,20,'#f7ead4');oval(c,-23,14,10,10,'#eed3a9');oval(c,23,14,10,10,'#eed3a9');eyes(c,12,0,3);nose(c,0,12,3,'#a55f59');cheeks(c);line(c,[[-1,19],[-1,24],[3,24],[3,19]],'#fffdf2',2);}
 else if(level===1){poly(c,[[-32,-9],[-25,-37],[-5,-23]],'#b58b6b','#80604a',.6);poly(c,[[32,-9],[25,-37],[5,-23]],'#b58b6b','#80604a',.6);poly(c,[[-25,-28],[-21,-13],[-12,-22]],'#dba6a0');poly(c,[[25,-28],[21,-13],[12,-22]],'#dba6a0');head(c,['#e6caaa','#bd9577','#987159']);oval(c,0,17,19,15,'#f5e8d3');for(const side of [-1,1])line(c,[[side*5,-23],[side*3,-13]],'#806551',2.4);eyes(c);nose(c,0,10,2.8,'#a46b68');whiskers(c,18,15);}
 else if(level===2){ear(c,-29,2,11,26,'#8b6044','#ba875e',-.25);ear(c,29,2,11,26,'#8b6044','#ba875e',.25);head(c,['#e6bb89','#bc8658','#906442'],29,31,2);oval(c,0,18,19,16,'#f4dfbc');eyes(c,12,-3,3);nose(c,0,13,5,'#473b32');oval(c,1,27,4,6,'#d8948e');line(c,[[1,25],[1,30]],'#ae6d69',.6);}
 else if(level===3){ear(c,-15,-22,8,22,'#e8ded5','#dcb5b3',-.14);ear(c,15,-22,8,22,'#e8ded5','#dcb5b3',.14);head(c,['#fff7e8','#e5d7cc','#bbaea8'],31,29,13);oval(c,0,24,18,13,'#fff8ec');eyes(c,12,9,2.7);nose(c,0,20,2.7,'#bd7f81');cheeks(c,21,20);whiskers(c,17,24);}
 else if(level===4){poly(c,[[-33,-7],[-24,-39],[-3,-19]],'#c77c46','#865331');poly(c,[[33,-7],[24,-39],[3,-19]],'#c77c46','#865331');poly(c,[[-24,-30],[-20,-13],[-10,-20]],'#4b3b32');poly(c,[[24,-30],[20,-13],[10,-20]],'#4b3b32');head(c,['#f0b773','#d58243','#a65f35'],34,30,4);poly(c,[[-33,5],[-11,10],[0,30],[-24,27]],'#f9e8ca');poly(c,[[33,5],[11,10],[0,30],[24,27]],'#f9e8ca');eyes(c,14,-1);nose(c,0,19,4,'#453b31');}
 else if(level===5){ear(c,-24,-20,10,11,'#8e8f82','#575c53');ear(c,24,-20,10,11,'#8e8f82','#575c53');head(c,['#d0d0bc','#959a8c','#6e766d']);oval(c,0,19,20,16,'#e9e5cf');for(const side of [-1,1])oval(c,side*16,1,15,9,'#404b47',null,1,side*-.25);eyes(c,14,0,2.4);nose(c,0,15,4,'#34403a');for(const x of [-7,7])line(c,[[x,-23],[x*.7,-13]],'#657166',2);}
 else if(level===6){ear(c,-29,-11,16,17,'#8f9e9d','#d9dbcd',-.3);ear(c,29,-11,16,17,'#8f9e9d','#d9dbcd',.3);head(c,['#dbe2d9','#99aaa8','#6a8585'],28,31,6);eyes(c,13,0,2.5);oval(c,0,10,7,12,gradient(c,['#565c58','#283d3b']));line(c,[[-3,26],[3,26]],'#51645c',1);cheeks(c,21,13);}
 else if(level===7){ear(c,-24,-22,10,11,'#34413a','#566357');ear(c,24,-22,10,11,'#34413a','#566357');head(c,['#fffdf0','#e9ebdc','#bec8b6'],35,33,4);for(const side of [-1,1])oval(c,side*15,-1,10,14,'#354139',null,1,side*-.37);eyes(c,13,-3,2.2);oval(c,0,20,17,13,'#fff8e3');nose(c,0,12,4,'#344038');}
 else if(level===8){for(let i=0;i<15;i++){const a=i*T/15;oval(c,Math.cos(a)*29,Math.sin(a)*29+2,12,13,gradient(c,['#bc8548','#976333','#715032']),null,1,a);}ear(c,-23,-19,8,9,'#c39858');ear(c,23,-19,8,9,'#c39858');head(c,['#f8d48c','#dcad5f','#bc8a45'],27,29,4);oval(c,0,18,17,14,'#f9e1ad');eyes(c,11,-1);nose(c,0,12,4,'#755039');}
 else if(level===9){ear(c,-24,-22,10,11,'#dba04f','#e8d1a1');ear(c,24,-22,10,11,'#dba04f','#e8d1a1');head(c,['#f5cd85','#e3a045','#b77332']);oval(c,0,19,21,16,'#fff0cf');for(const side of [-1,1]){poly(c,[[side*30,-14],[side*17,-9],[side*30,-6]],'#5d4432');poly(c,[[side*34,2],[side*21,5],[side*33,9]],'#5d4432');poly(c,[[side*5,-25],[side*3,-14],[side*10,-23]],'#5d4432');}eyes(c);nose(c,0,12,4,'#98614a');whiskers(c,18,19);}
 else if(level===10){ear(c,-30,1,8,11,'#596562','#a0a49a');ear(c,30,1,8,11,'#596562','#a0a49a');head(c,['#8c9790','#5f706a','#3d534e'],35,35,2);oval(c,0,15,25,23,gradient(c,['#abb2a6','#7f8f84','#586d63']));oval(c,0,3,29,15,'#87968a');eyes(c,13,0,2.7);oval(c,0,14,10,6,'#4a5a50');oval(c,-4,14,2,1.7,'#273e34');oval(c,4,14,2,1.7,'#273e34');line(c,[[-10,27],[0,29],[10,27]],'#43584c',1.1);}
 else if(level===11){ear(c,-28,0,17,28,'#8ba1a8','#c2b6b1',-.2);ear(c,28,0,17,28,'#8ba1a8','#c2b6b1',.2);head(c,['#d1dde0','#9aafb5','#738d96'],25,30,0);eyes(c,13,-2,2.3);c.beginPath();c.moveTo(-7,10);c.bezierCurveTo(-9,24,-9,42,3,42);c.bezierCurveTo(13,42,17,32,11,29);c.strokeStyle='#708c95';c.lineWidth=13;c.stroke();c.strokeStyle='#b8cace';c.lineWidth=9;c.stroke();for(let i=0;i<3;i++)line(c,[[-4,18+i*5],[4,18+i*5]],'#819ba2',.7);}
 else if(level===12){for(const side of [-1,1]){line(c,[[side*13,-20],[side*15,-37]],'#ad8956',5);oval(c,side*15,-39,4,4,'#7f6747');ear(c,side*29,-15,13,6,'#d6b66c','#ae8650',side*.5);}head(c,['#f9dfa0','#deba6b','#b99353'],25,32,7);for(const [x,y,r]of[[-13,-13,5],[14,-8,5],[-17,7,5],[17,10,4],[0,-20,4]])oval(c,x,y,r,r*.9,'#aa7b43');oval(c,0,26,22,15,'#f0d498');eyes(c,12,1);oval(c,-8,26,2,1.7,'#957245');oval(c,8,26,2,1.7,'#957245');line(c,[[-7,33],[0,35],[7,33]],'#a88751',.8);}
 else if(level===13){poly(c,[[-23,12],[-44,-8],[-42,18],[-30,22]],'#5a94a9','#39768b');poly(c,[[-8,-15],[2,-37],[15,-15]],'#5a94a9','#39768b');oval(c,1,6,33,27,gradient(c,['#a9d6df','#6ba8bd','#3b7795']),'#3e7790',.7);poly(c,[[23,-1],[45,5],[26,15]],'#7bb4c5','#52869a',.6);oval(c,5,19,22,12,'#d3e4dd');oval(c,22,-2,3,3.5,'#234d60');oval(c,21,-3,.8,.8,'#e9f8fa');line(c,[[27,11],[33,12],[39,9]],'#39738a',.9);}
 else{poly(c,[[-23,9],[-44,-12],[-43,8],[-34,22],[-25,22]],'#3e718c','#2b5a74');oval(c,3,6,36,30,gradient(c,['#91c0d0','#4e8ca9','#2d5e80']),'#2e607b',.8);oval(c,13,25,23,10,'#c2d9da');poly(c,[[-4,21],[-4,43],[13,31]],'#397796','#2c627f');oval(c,25,3,2.8,3.3,'#183e54');oval(c,24,2,.8,.8,'#f4fbff');line(c,[[25,18],[32,16],[36,11]],'#2a5f7a',1.2);line(c,[[1,-24],[1,-33]],'#72bacb',2.2);c.strokeStyle='#8cc9d5';c.lineWidth=2.4;for(const side of [-1,1]){c.beginPath();c.moveTo(1,-29);c.quadraticCurveTo(side*7,-45,side*15,-36);c.stroke();}oval(c,-15,-35,2,3,'#93cfd8');oval(c,16,-36,2,3,'#93cfd8');}
 c.restore();}
export function drawAnimal(c,level,x,y,r,rotation=0,alpha=1){level=Math.max(0,Math.min(14,level|0));c.save();c.translate(x,y);c.rotate(rotation);c.scale(r/45,r/45);c.globalAlpha*=alpha;drawCachedSkin(c,'zoo',level,paint);c.restore();}
